package org.jackhuang.hmcl.script;

import org.jackhuang.hmcl.server.RuntimeSession;
import org.jetbrains.annotations.NotNullByDefault;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.Unmodifiable;
import java.util.*;
import java.util.concurrent.*;

/// Implements bounded observations, block interactions and input restricted to the selected game.
@NotNullByDefault
final class ScriptFoundationHost {
    /// Parent adapter supplies authenticated serialized requests and existing camera operations.
    private final ScriptGameHost host;
    /// Stable instance identity and temporary input ownership.
    private final String key, owner;
    /// Last delivered event; each script consumes its own independent observation stream.
    private long cursor;
    /// Tracks cleanup requirements without touching other scripts' resources.
    private boolean inputUsed, miningUsed;
    /// Stops refreshing keys once cleanup starts.
    private volatile boolean closed;
    /// Optional heartbeat for keys explicitly held across statements.
    private @Nullable ScheduledFuture<?> heartbeat;
    /// One daemon performs short input heartbeats; abandoned keys also expire in the game.
    private static final ScheduledExecutorService TIMER = Executors.newSingleThreadScheduledExecutor(task -> { Thread t = new Thread(task, "OchreScript input heartbeat"); t.setDaemon(true); return t; });
    /// All functions routed to this adapter.
    private static final @Unmodifiable Set<String> FUNCTIONS = Set.of("player.events", "player.snapshot", "world.block", "world.target_block", "player.lock_block", "player.mine", "player.place_block", "game.logs", "input.key", "input.send_key", "input.key_down", "input.key_up", "input.text", "input.send_text", "chat.send", "task.load", "task.save", "task.clear", "world.target", "world.collision", "world.can_stand", "world.path_clear", "player.item_tags", "player.item_is", "player.container_slots", "player.container_move", "player.container_swap", "player.container_quick_move", "script.wait_event", "input.snapshot", "input.pressed_keys", "input.is_key_down");
    /// Binds to one explicitly selected game, without exposing arbitrary network destinations.
    ScriptFoundationHost(ScriptGameHost host, String key, String owner) { this.host = host; this.key = key; this.owner = owner; }
    /// Tests routing without accepting unknown function names.
    static boolean supports(String name) { return FUNCTIONS.contains(name); }
    /// Rejects unknown and duplicate argument names before requesting game effects.
    private static @Unmodifiable Map<String, Object> bind(List<Object> positional, Map<String, Object> named, String... names) {
        if (positional.size() > names.length) throw new IllegalArgumentException("Too many arguments"); Map<String, Object> result = new LinkedHashMap<>();
        for (int i = 0; i < positional.size(); i++) result.put(names[i], positional.get(i));
        for (var e : named.entrySet()) { if (!Arrays.asList(names).contains(e.getKey())) throw new IllegalArgumentException("Unknown argument: " + e.getKey()); if (result.putIfAbsent(e.getKey(), e.getValue()) != null) throw new IllegalArgumentException("Duplicate argument: " + e.getKey()); }
        return Map.copyOf(result);
    }
    /// Gets a required argument without inventing absent coordinates or text.
    private static Object arg(Map<String, Object> args, String name) { @Nullable Object value = args.get(name); if (value == null) throw new IllegalArgumentException("Missing argument: " + name); return value; }
    /// Reads a mandatory protocol field.
    private static String field(Map<String, String> data, String name) { @Nullable String value = data.get(name); if (value == null) throw new IllegalArgumentException("Game capability unavailable: " + name); return value; }
    /// Preserves booleans and numeric event values while keeping identifiers and state text intact.
    private static Object scalar(String name, String value) { if (value.equals("true") || value.equals("false")) return Boolean.parseBoolean(value); if (value.matches("-?[0-9]+(?:\\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")) try { double number=Double.parseDouble(value); if(Double.isFinite(number))return number; } catch(NumberFormatException ignored) { } return value; }
    /// Decodes only bridge-produced records, discarding protocol metadata and internal bookkeeping.
    static @Unmodifiable Map<String,Object> record(Map<String,String> data) { Map<String,Object> result=new LinkedHashMap<>(); data.forEach((name,value)->{if(!Set.of("ok","protocol","gameVersion","bridgeVersion","capabilities","deadline","identity").contains(name))result.put(name,scalar(name,value));});return Map.copyOf(result); }
    /// Flattens only known observation fields, excluding protocol metadata and credentials.
    private static @Unmodifiable Map<String, Object> observation(Map<String,String> data) { Map<String,Object> result=new LinkedHashMap<>(); Map<String,Object> inputs=new LinkedHashMap<>(),vitals=new LinkedHashMap<>(),container=new LinkedHashMap<>(),screen=new LinkedHashMap<>(); for(var entry:data.entrySet()){String name=entry.getKey();Object value=scalar(name,entry.getValue());if(name.startsWith("input."))inputs.put(name.substring(6),value);else if(name.startsWith("vital."))vitals.put(name.substring(6),value);else if(name.startsWith("container."))container.put(name.substring(10),value);else if(name.startsWith("screen."))screen.put(name.substring(7),value);else if(!Set.of("ok","protocol","gameVersion","bridgeVersion","capabilities","deadline","identity").contains(name))result.put(name.startsWith("state.")?name.substring(6):name,value); } if(data.containsKey("x")&&data.containsKey("y")&&data.containsKey("z"))result.put("position",vector(data));if(!inputs.isEmpty())result.put("inputs",Map.copyOf(inputs));if(!vitals.isEmpty())result.put("vitals",Map.copyOf(vitals));if(!container.isEmpty())result.put("container",Map.copyOf(container));if(!screen.isEmpty())result.put("screen",Map.copyOf(screen));return Map.copyOf(result); }
    /// Decodes exact block coordinates rather than rounding an aim point twice.
    private static @Unmodifiable Map<String, Object> vector(Map<String, String> data) { return Map.of("x", Double.parseDouble(field(data, "x")), "y", Double.parseDouble(field(data, "y")), "z", Double.parseDouble(field(data, "z"))); }
    /// Builds a block record including collision hints; solid is not a full collision shape.
    private static @Unmodifiable Map<String, Object> block(Map<String, String> data) { Map<String, Object> result = new LinkedHashMap<>(); result.put("position", vector(data)); for (String name : List.of("world", "id", "state", "distance", "loaded", "isAir", "blocksMotion", "canBeReplaced", "face", "status")) if (data.containsKey(name)) result.put(switch (name) { case "isAir" -> "air"; case "blocksMotion" -> "solid"; case "canBeReplaced" -> "replaceable"; default -> name; }, scalar(name, field(data, name))); return Map.copyOf(result); }
    /// Accepts a Vec3 or a prior block record, retaining its world and expected block type.
    private @Unmodifiable Map<String, String> target(Object value) { if (!(value instanceof Map<?, ?> original)) throw new IllegalArgumentException("Expected Vec3 or block Record"); @Nullable Object nested = original.containsKey("position") ? original.get("position") : value; if (!(nested instanceof Map<?, ?> p)) throw new IllegalArgumentException("Expected block position"); Map<String, String> fields = new LinkedHashMap<>(); for (String axis : List.of("x", "y", "z")) { @Nullable Object coordinate = p.get(axis); double n = OchreScript.number(coordinate); if (!Double.isFinite(n) || Math.abs(n) > (axis.equals("y") ? 2048 : 30_000_000)) throw new IllegalArgumentException("Block coordinate out of range"); fields.put(axis, Integer.toString((int) Math.floor(n))); } for (String name : List.of("world", "id")) if (original.containsKey(name)) fields.put(name.equals("id") ? "expected" : name, String.valueOf(original.get(name))); fields.put("owner", owner); return Map.copyOf(fields); }
    /// Maps a documented block face to its canonical game direction.
    private static String face(Object value) { String name = String.valueOf(value); return switch (name) { case "up", "top" -> "up"; case "down", "bottom" -> "down"; case "north", "south", "east", "west" -> name; default -> throw new IllegalArgumentException("Unknown block face: " + name); }; }
    /// Validates a short duration before any control is acquired.
    private static double seconds(Map<String, Object> args, String name, double fallback, double max) { double n = args.containsKey(name) ? OchreScript.quantity(arg(args, name), "time") : fallback; if (!Double.isFinite(n) || n <= 0 || n > max) throw new IllegalArgumentException(name + " must be in (0s, " + max + "s]"); return n; }
    /// Aims slightly inside the requested face, then lets the game perform its own raycast.
    private void aim(Map<String, String> fields, String face, OchreScript.Control control) throws Exception { host.call("player.look_at_block", List.of(vector(fields)), Map.of("face", face), control); }
    /// Refreshes only this run's leased keys and never reacquires an expired lease.
    private void startHeartbeat() { inputUsed = true; if (heartbeat == null) heartbeat = TIMER.scheduleWithFixedDelay(() -> { if (!closed) try { host.request("script.input.heartbeat", Map.of("owner", owner)); } catch (Exception ignored) { } }, 150, 150, TimeUnit.MILLISECONDS); }
    /// Runs validated operations, with polling loops interruptible through the shared script control.
    Object call(String name, List<Object> positional, Map<String, Object> named, OchreScript.Control control) throws Exception {
        control.check();
        if(name.startsWith("task.")){var args=bind(positional,named,name.equals("task.load")?new String[]{"name","default"}:name.equals("task.save")?new String[]{"name","value"}:new String[]{"name"});Object value=arg(args,"name");if(!(value instanceof String checkpoint))throw new IllegalArgumentException("Task name must be a string");if(name.equals("task.load"))return TaskState.load(key,checkpoint,args.getOrDefault("default",OchreScript.Empty.NONE));if(name.equals("task.clear"))return TaskState.clear(key,checkpoint);TaskState.save(key,checkpoint,arg(args,"value"));return OchreScript.Empty.NONE;}
        if(name.equals("world.target")){bind(positional,named);return record(host.request("script.target",Map.of()));}
        if(Set.of("world.collision","world.can_stand","world.path_clear").contains(name)){var args=bind(positional,named,"position");Object value=arg(args,"position");if(!(value instanceof Map<?,?> position))throw new IllegalArgumentException("Expected Vec3");Map<String,String> fields=new LinkedHashMap<>();for(String axis:List.of("x","y","z"))fields.put(axis,Double.toString(OchreScript.number(position.get(axis))));fields.put("path",Boolean.toString(name.equals("world.path_clear")));var data=host.request("script.collision",fields);return name.equals("world.collision")?record(data):Boolean.parseBoolean(field(data,name.equals("world.can_stand")?"can_stand":"path_clear"));}
        if(name.equals("player.item_tags")||name.equals("player.item_is")){var args=bind(positional,named,name.equals("player.item_is")?new String[]{"tag"}:new String[]{});var data=host.request("script.item.tags",Map.of());List<String> tags=new ArrayList<>();int count=Integer.parseInt(field(data,"count"));if(count<0||count>128)throw new IllegalArgumentException("Invalid tag count");for(int i=0;i<count;i++)tags.add(field(data,"tag."+i));return name.equals("player.item_is")?tags.contains(String.valueOf(arg(args,"tag"))):List.copyOf(tags);}
        if(name.equals("player.container_slots")){var args=bind(positional,named,"offset","limit");var data=host.request("script.container.read",Map.of("offset",Integer.toString(exactInt(OchreScript.number(args.getOrDefault("offset",0.0)),0,512)),"limit",Integer.toString(exactInt(OchreScript.number(args.getOrDefault("limit",24.0)),1,24))));int count=Integer.parseInt(field(data,"count"));if(count<0||count>24)throw new IllegalArgumentException("Invalid slots");List<Object> slots=new ArrayList<>();for(int i=0;i<count;i++){String prefix="slot."+i+".";Map<String,String> row=new LinkedHashMap<>();data.forEach((k,v)->{if(k.startsWith(prefix))row.put(k.substring(prefix.length()),v);});slots.add(record(row));}return Map.of("token",field(data,"menu_token"),"total",Double.parseDouble(field(data,"total")),"slots",List.copyOf(slots));}
        if(name.startsWith("player.container_")){boolean quick=name.equals("player.container_quick_move"),swap=name.equals("player.container_swap");var args=bind(positional,named,quick?new String[]{"from","token"}:swap?new String[]{"from","to","token"}:new String[]{"from","to","count","token"});Map<String,String> fields=new LinkedHashMap<>();fields.put("action",quick?"quick_move":swap?"swap":"move");fields.put("from",Integer.toString(exactInt(OchreScript.number(arg(args,"from")),0,511)));if(!quick)fields.put("to",Integer.toString(exactInt(OchreScript.number(arg(args,"to")),0,511)));fields.put("count",Integer.toString(exactInt(OchreScript.number(args.getOrDefault("count",0.0)),0,64)));fields.put("menu_token",String.valueOf(arg(args,"token")));return field(host.request("script.container.act",fields),"status");}
        if (Set.of("input.snapshot", "input.pressed_keys", "input.is_key_down").contains(name)) { var args = name.equals("input.is_key_down") ? bind(positional, named, "key") : bind(positional, named); var data = host.request("script.input.read", Map.of()); int count = Integer.parseInt(field(data, "keys")), mouseCount = Integer.parseInt(field(data,"mouse_buttons")); if(count<0||count>317||mouseCount<0||mouseCount>8)throw new IllegalArgumentException("Invalid input snapshot"); List<Object> keys = new ArrayList<>(), mouse = new ArrayList<>(); for(int i=0;i<count;i++)keys.add(Map.of("code",Double.parseDouble(field(data,"key."+i+".code")),"name",field(data,"key."+i+".name"))); for(int i=0;i<mouseCount;i++)mouse.add(Double.parseDouble(field(data,"mouse."+i))); if(name.equals("input.is_key_down")){Object value=arg(args,"key"); if(value instanceof String text) value = switch(text.toUpperCase(java.util.Locale.ROOT)) { case "SHIFT" -> "LEFT_SHIFT"; case "CONTROL" -> "LEFT_CONTROL"; case "ALT" -> "LEFT_ALT"; case "SUPER" -> "LEFT_SUPER"; default -> text; }; for(Object item:keys){var entry=(Map<?,?>)item;if(value instanceof String text&&text.equalsIgnoreCase(String.valueOf(entry.get("name")))||value instanceof Double&&value.equals(entry.get("code")))return true;}return false;} return name.equals("input.pressed_keys") ? List.copyOf(keys) : Map.of("focused",Boolean.parseBoolean(field(data,"focused")),"keys",List.copyOf(keys),"mouse_buttons",List.copyOf(mouse),"position",Map.of("x",Double.parseDouble(field(data,"x")),"y",Double.parseDouble(field(data,"y")))); }
        if (name.equals("script.wait_event")) { var args=bind(positional,named,"type","timeout"); String eventType=String.valueOf(arg(args,"type")); double timeout=seconds(args,"timeout",5,60); long end=control.now()+(long)(timeout*1e9); do{control.check();Object events=call("player.events",List.of(),Map.of(),control);for(Object item:(List<?>)events)if(item instanceof Map<?,?> entry&&eventType.equals(entry.get("type")))return item;control.sleep(.05);}while(control.now()<end);return OchreScript.Empty.NONE; }
        if (name.equals("player.events") || name.equals("player.snapshot")) { bind(positional, named); if (name.equals("player.snapshot")) return observation(host.request("script.snapshot", Map.of())); var data = host.request("script.observe", Map.of("cursor", Long.toString(cursor))); int count = Integer.parseInt(field(data, "count")); if (count < 0 || count > 64) throw new IllegalArgumentException("Invalid event count"); List<Object> events = new ArrayList<>(); if ("true".equals(data.get("missed"))) events.add(Map.of("type", "overflow")); for (int i = 0; i < count; i++) { Map<String, String> entry = new LinkedHashMap<>(); String prefix = "event." + i + "."; data.forEach((k, v) -> { if (k.startsWith(prefix)) entry.put(k.substring(prefix.length()), v); }); events.add(observation(entry)); } cursor = Long.parseLong(field(data, "cursor")); return List.copyOf(events); }
        if (name.equals("world.block")) { var args = bind(positional, named, "position"); return block(host.request("script.block.read", target(arg(args, "position")))); }
        if (name.equals("world.target_block")) { bind(positional, named); var data = host.request("script.block.target", Map.of()); return "true".equals(field(data, "found")) ? block(data) : OchreScript.Empty.NONE; }
        if (name.equals("game.logs")) { var args = bind(positional, named, "limit"); double n = OchreScript.number(args.getOrDefault("limit", 40.0)); if (n != Math.rint(n) || n < 1 || n > 100) throw new IllegalArgumentException("Log limit must be 1..100"); String[] lines = RuntimeSession.game(key).log().split("\\R"); List<String> result = new ArrayList<>(); for (int i = Math.max(0, lines.length - (int) n); i < lines.length; i++) if (!lines[i].isEmpty()) result.add(redact(lines[i])); return List.copyOf(result); }
        if (Set.of("input.text", "input.send_text", "chat.send").contains(name)) { var args = bind(positional, named, "text"); if (!(arg(args, "text") instanceof String text)) throw new IllegalArgumentException("Expected text string"); return field(host.request(name.equals("chat.send") ? "script.chat" : "script.input.text", Map.of("text", text, "open_chat", Boolean.toString(name.equals("input.text")))), "status"); }
        if (name.startsWith("input.")) {
            boolean raw = name.equals("input.send_key"), down = name.equals("input.key_down"), up = name.equals("input.key_up"); var args = raw ? bind(positional, named, "key", "action", "modifiers") : down || up ? bind(positional, named, "key", "modifiers") : bind(positional, named, "key", "duration", "modifiers");
            Object key = arg(args, "key"); String code = key instanceof Double d ? Integer.toString(exactInt(d, 32, 348)) : key instanceof String text ? text : ""; if (code.isEmpty()) throw new IllegalArgumentException("Expected key name or numeric GLFW code"); int mods = exactInt(OchreScript.number(args.getOrDefault("modifiers", 0.0)), 0, 15); String action = raw ? String.valueOf(args.getOrDefault("action", "press")) : up ? "release" : "press"; double duration = !raw && !down && !up ? seconds(args, "duration", .1, 30) : 0;
            Map<String, String> fields = Map.of("owner", owner, "key", code, "modifiers", Integer.toString(mods), "action", action); inputUsed = true; var data = host.request("script.input.key", fields); if ("true".equals(data.get("leased"))) startHeartbeat(); if (duration > 0) try { control.sleep(duration); } finally { host.request("script.input.key", Map.of("owner", owner, "key", code, "modifiers", Integer.toString(mods), "action", "release", "require_handled", "false")); } return field(data, "status");
        }
        if (!Set.of("player.lock_block", "player.mine", "player.place_block").contains(name)) throw new IllegalArgumentException("Unknown foundation operation");
        var args = bind(positional, named, "position", "face", name.equals("player.lock_block") ? "duration" : "timeout"); String face = face(args.getOrDefault("face", "up")); double timeout = seconds(args, name.equals("player.lock_block") ? "duration" : "timeout", name.equals("player.lock_block") ? 2 : name.equals("player.mine") ? 30 : 2, 60);
        var initial = host.request("script.block.read", target(arg(args, "position"))); if ("true".equals(initial.get("isAir"))) throw new IllegalArgumentException("Target block is air"); Map<String, String> fields = new LinkedHashMap<>(target(block(initial))); fields.put("face", face); long deadline = control.now() + (long) (timeout * 1e9);
        if (name.equals("player.place_block")) { aim(fields, face, control); var placed = host.request("script.block.place", fields); Map<String, String> destination = new LinkedHashMap<>(target(block(placed))); destination.remove("expected"); while (control.now() < deadline) { control.sleep(.1); var result = host.request("script.block.read", destination); if (!field(result, "state").equals(field(placed, "before")) && !"true".equals(result.get("isAir"))) { control.sleep(.2); result = host.request("script.block.read", destination); if (!field(result, "state").equals(field(placed, "before")) && !"true".equals(result.get("isAir"))) { Map<String, String> observed = new LinkedHashMap<>(result); observed.put("status", "client_observed_placement"); return block(observed); } } } throw new IllegalArgumentException("Placement not observed; check materials, permissions and selected block"); }
        try {
            while (control.now() < deadline) { control.check(); Map<String, String> query = new LinkedHashMap<>(fields); query.remove("expected"); var current = host.request("script.block.read", query); if (!field(current, "world").equals(field(initial, "world"))) throw new IllegalArgumentException("Target world changed");
                if ("true".equals(current.get("isAir")) && name.equals("player.mine")) { control.sleep(.2); current = host.request("script.block.read", query); if ("true".equals(current.get("isAir"))) return "client_observed_break"; }
                if (!field(current, "id").equals(field(initial, "id"))) throw new IllegalArgumentException("Target block changed"); aim(fields, face, control);
                if (name.equals("player.mine")) { miningUsed = true; host.request("script.block.mine", fields); } control.sleep(.1);
            }
            if (name.equals("player.lock_block")) return "lock_duration_complete"; throw new IllegalArgumentException("Mining timed out; check tool, reach and server permissions");
        } finally { if (miningUsed) { host.request("script.block.stop", Map.of("owner", owner)); miningUsed = false; } }
    }
    /// Converts key/modifier integers without truncation or non-finite casts.
    private static int exactInt(double n, int min, int max) { if (!Double.isFinite(n) || n != Math.rint(n) || n < min || n > max) throw new IllegalArgumentException("Expected integer in [" + min + ", " + max + "]"); return (int) n; }
    /// Removes common credentials from game log lines before returning them to a script.
    static String redact(String line) { return line.replaceAll("(?i)Bearer\\s+[^\\s,;]+", "Bearer [redacted]").replaceAll("(?i)(accessToken|refreshToken|clientToken|authorization|token)([\\s:=\\\"]+)[^\\s,;\\\"]+", "$1$2[redacted]"); }
    /// Releases both resources even when either game request fails; game watchdogs provide a second cleanup path.
    void close() throws Exception { closed = true; @Nullable var task = heartbeat; if (task != null) task.cancel(false); try { if (inputUsed) host.request("script.input.release", Map.of("owner", owner)); } finally { if (miningUsed) host.request("script.block.stop", Map.of("owner", owner)); } }
}
